// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.brain.intent.contextimport com.roshan.persona.brain.context.BrainContextimport com.roshan.persona.brain.context.Expectationimport javax.inject.Injectimport javax.inject.Singleton/** * NOUS — Contextual Pre-Processor (Fixes #26 — coreference resolution). * * If a previous turn left an "expectation" (skill asked for input, or intent * was ambiguous), the new utterance is appended to the previous one for * classification. * * Example: *   Turn 1: "Open my calendar" → OpenApp(calendar) + Expectation.AwaitingChoice *   Turn 2: "Cancel the 3 PM one" *     → Appended: "Open my calendar. Cancel the 3 PM one" *     → Stage 3 embedding can now match CancelEvent intent *     → Stage 4 NER extracts "3 PM" as time slot * * @see <a href="docs/spec/module2-spec-review.pdf">§4.6 ContextualOverride</a> */@Singletonclass ContextualPreProcessor @Inject constructor() {    /**     * Apply contextual override to [rawInput] based on [brainContext].     *     * @return possibly-modified input string with previous turn prepended     */    fun applyContext(rawInput: String, brainContext: BrainContext): String {        val expectation = brainContext.pendingExpectation ?: return rawInput        val lastTurn = brainContext.conversationHistory.lastOrNull()?.userText            ?: return rawInput        // Only append if the new input looks like a continuation (short, no verb)        // or if the expectation explicitly requires context        return when (expectation) {            is Expectation.AwaitingContact -> {                // User is likely responding with a contact name                // Append to give classifier context                "$lastTurn. $rawInput"            }            is Expectation.AwaitingChoice -> {                // User is likely responding with "the 3 PM one" or "first one"                // Append to give classifier context                "$lastTurn. $rawInput"            }            is Expectation.AwaitingConfirmation -> {                // User is likely responding with "yes" or "no"                // Append to give classifier context                "$lastTurn. $rawInput"            }        }    }    /**     * Check if [rawInput] looks like a continuation (short, no clear verb).     * Used to decide whether contextual override is needed.     */    fun looksLikeContinuation(rawInput: String): Boolean {        val tokens = rawInput.lowercase().split(Regex("[^a-z0-9]+")).filter { it.isNotBlank() }        if (tokens.size > 5) return false  // long input = standalone        val standaloneVerbs = setOf(            "call", "send", "open", "search", "set", "create", "delete",            "turn", "enable", "disable", "play", "pause", "stop",            "torch", "volume", "brightness", "mute", "unmute",            "yes", "no", "ok", "sure", "cancel", "confirm",            "alarm", "timer", "reminder", "note", "calendar",            "translate", "summarize", "explain",        )        // If first token is a standalone verb → not a continuation        return tokens.firstOrNull() !in standaloneVerbs    }}